1	package wallet
2	
3	import (
4		"fmt"
5		"strings"
6		"sync"
7		"time"
8	)
9	
10	// Wallet 是进程内的智能钱包。
11	//
12	// 所有方法都可被多个 goroutine 并发调用；每一次申请、结算或取消都在
13	// 同一把锁内原子完成，因此余额与共享累计额度不会被超扣，同一请求也
14	// 只会产生一个终态。状态仅在当前 Wallet 实例的生命周期内保留。
15	type Wallet struct {
16		mu sync.Mutex
17	
18		// now 可在同包测试中替换，默认使用 time.Now。
19		now func() time.Time
20	
21		accounts map[string]*account
22		sessions map[string]*session
23		policies map[string]*policy
24		// requests 以“使用账户编号 + 请求编号”为键，实现按使用账户的幂等。
25		requests map[requestKey]*request
26		ledger   []LedgerEntry
27	}
28	
29	type account struct {
30		id        string
31		available int64
32		reserved  int64
33		createdAt time.Time
34	}
35	
36	type session struct {
37		id        string
38		accountID string
39		deviceID  string
40		expiresAt time.Time
41		revoked   bool
42		createdAt time.Time
43	}
44	
45	type policy struct {
46		id                string
47		payerAccountID    string
48		allowedAccounts   map[string]struct{}
49		operation         string
50		payee             string
51		startsAt          time.Time
52		endsAt            time.Time
53		maxPerRequest     int64
54		maxTotal          int64
55		approvalThreshold int64
56		approvalWait      time.Duration
57		reservedTotal     int64
58		spentTotal        int64
59	
60		deactivated          bool
61		deactivatedAt        time.Time
62		deactivatorAccountID string
63		deactivateReason     string
64	}
65	
66	type request struct {
67		policyID          string
68		requestID         string
69		accountID         string
70		payerAccountID    string
71		sessionID         string
72		operation         string
73		payee             string
74		estimatedFee      int64
75		actualFee         int64
76		state             RequestState
77		createdAt         time.Time
78		settledAt         time.Time
79		waitDeadline      time.Time
80		decidedAt         time.Time
81		approverAccountID string
82		rejectReason      string
83	}
84	
85	type requestKey struct {
86		accountID string
87		requestID string
88	}
89	
90	// New 创建一个空钱包。
91	func New() *Wallet {
92		return &Wallet{
93			now:      time.Now,
94			accounts: make(map[string]*account),
95			sessions: make(map[string]*session),
96			policies: make(map[string]*policy),
97			requests: make(map[requestKey]*request),
98		}
99	}
100	
101	// CreateAccount 创建具有唯一编号和初始代付余额的账户。
102	//
103	// 金额为最小货币单位的整数；初始余额为负或编号重复时返回错误，
104	// 且不会改动任何已有资金记录。
105	func (w *Wallet) CreateAccount(id string, initialBalance int64) (AccountView, error) {
106		if id == "" {
107			return AccountView{}, ErrEmptyAccountID
108		}
109		if initialBalance < 0 {
110			return AccountView{}, fmt.Errorf("%w: initial balance must not be negative", ErrInvalidAmount)
111		}
112	
113		w.mu.Lock()
114		defer w.mu.Unlock()
115	
116		if _, ok := w.accounts[id]; ok {
117			return AccountView{}, fmt.Errorf("%w: %s", ErrAccountExists, id)
118		}
119		now := w.now()
120		acc := &account{id: id, available: initialBalance, createdAt: now}
121		w.accounts[id] = acc
122		return acc.view(), nil
123	}
124	
125	// Account 查询账户视图；账户不存在时返回 ErrAccountNotFound。
126	func (w *Wallet) Account(id string) (AccountView, error) {
127		w.mu.Lock()
128		defer w.mu.Unlock()
129	
130		acc, ok := w.accounts[id]
131		if !ok {
132			return AccountView{}, fmt.Errorf("%w: %s", ErrAccountNotFound, id)
133		}
134		return acc.view(), nil
135	}
136	
137	// Balance 查询账户的可用余额与预留余额。
138	func (w *Wallet) Balance(id string) (Balances, error) {
139		view, err := w.Account(id)
140		if err != nil {
141			return Balances{}, err
142		}
143		return view.Balances, nil
144	}
145	
146	// CreateSession 为账户创建一个绑定设备、带到期时间的会话。
147	//
148	// 会话编号全局唯一；账户必须存在。
149	func (w *Wallet) CreateSession(id, accountID, deviceID string, expiresAt time.Time) (SessionView, error) {
150		if id == "" || accountID == "" || deviceID == "" {
151			return SessionView{}, fmt.Errorf("%w: session id, account id and device id are required", ErrInvalidArgument)
152		}
153	
154		w.mu.Lock()
155		defer w.mu.Unlock()
156	
157		if _, ok := w.accounts[accountID]; !ok {
158			return SessionView{}, fmt.Errorf("%w: %s", ErrAccountNotFound, accountID)
159		}
160		if _, ok := w.sessions[id]; ok {
161			return SessionView{}, fmt.Errorf("%w: %s", ErrSessionExists, id)
162		}
163		now := w.now()
164		sess := &session{
165			id:        id,
166			accountID: accountID,
167			deviceID:  deviceID,
168			expiresAt: expiresAt,
169			createdAt: now,
170		}
171		w.sessions[id] = sess
172		return sess.view(), nil
173	}
174	
175	// RevokeSession 主动吊销会话。会话不存在返回错误；重复吊销视为成功。
176	// 吊销后不再受理该会话的新申请；仍在待审批的请求进入拒绝终态并说明
177	// 原因，已预留费用的请求仍可结算或取消。
178	func (w *Wallet) RevokeSession(id string) error {
179		w.mu.Lock()
180		defer w.mu.Unlock()
181	
182		sess, ok := w.sessions[id]
183		if !ok {
184			return fmt.Errorf("%w: %s", ErrSessionNotFound, id)
185		}
186		if sess.revoked {
187			return nil
188		}
189		sess.revoked = true
190		now := w.now()
191		reason := "application session revoked before approval"
192		// 仍在待审批的请求随会话吊销进入拒绝终态。
193		for _, req := range w.requests {
194			if req.state == RequestPendingApproval && req.sessionID == sess.id {
195				req.state = RequestRejected
196				req.rejectReason = reason
197				req.decidedAt = now
198				w.ledger = append(w.ledger, LedgerEntry{
199					Kind:      LedgerRejection,
200					AccountID: req.accountID,
201					RequestID: req.requestID,
202					Reason:    reason,
203					At:        now,
204				})
205			}
206		}
207		return nil
208	}
209	
210	// Session 查询会话视图。
211	func (w *Wallet) Session(id string) (SessionView, error) {
212		w.mu.Lock()
213		defer w.mu.Unlock()
214	
215		sess, ok := w.sessions[id]
216		if !ok {
217			return SessionView{}, fmt.Errorf("%w: %s", ErrSessionNotFound, id)
218		}
219		return sess.view(), nil
220	}
221	
222	// SavePolicy 保存（创建）一条代付策略。
223	//
224	// 出资账户和所有使用账户必须存在，限额必须为正，开始时间必须严格早于
225	// 结束时间，编号不得重复，否则拒绝保存并返回包装了具体原因的错误。
226	func (w *Wallet) SavePolicy(spec PolicySpec) error {
227		if spec.ID == "" {
228			return fmt.Errorf("%w: policy id is required", ErrPolicyInvalid)
229		}
230		if spec.Operation == "" || spec.Payee == "" {
231			return fmt.Errorf("%w: operation and payee are required", ErrPolicyInvalid)
232		}
233		if spec.MaxPerRequest <= 0 || spec.MaxTotal <= 0 {
234			return fmt.Errorf("%w: limits must be positive", ErrPolicyInvalid)
235		}
236		// 审批门槛：零表示关闭；不得为负，不得超过单次上限；开启时等待时长必须为正。
237		if spec.ApprovalThreshold < 0 {
238			return fmt.Errorf("%w: approval threshold must not be negative", ErrPolicyInvalid)
239		}
240		if spec.ApprovalThreshold > 0 {
241			if spec.ApprovalThreshold > spec.MaxPerRequest {
242				return fmt.Errorf("%w: approval threshold %d exceeds per-request limit %d", ErrPolicyInvalid, spec.ApprovalThreshold, spec.MaxPerRequest)
243			}
244			if spec.ApprovalWait <= 0 {
245				return fmt.Errorf("%w: approval wait must be positive when approval is enabled", ErrPolicyInvalid)
246			}
247		}
248		if !spec.StartsAt.Before(spec.EndsAt) {
249			return fmt.Errorf("%w: starts-at must be before ends-at", ErrPolicyInvalid)
250		}
251		if spec.PayerAccountID == "" || len(spec.AllowedAccountIDs) == 0 {
252			return fmt.Errorf("%w: payer account and at least one allowed account are required", ErrPolicyInvalid)
253		}
254	
255		w.mu.Lock()
256		defer w.mu.Unlock()
257	
258		if _, ok := w.policies[spec.ID]; ok {
259			return fmt.Errorf("%w: %s", ErrPolicyExists, spec.ID)
260		}
261		if _, ok := w.accounts[spec.PayerAccountID]; !ok {
262			return fmt.Errorf("%w: payer account %q: %w", ErrPolicyInvalid, spec.PayerAccountID, ErrAccountNotFound)
263		}
264		allowed := make(map[string]struct{}, len(spec.AllowedAccountIDs))
265		for _, id := range spec.AllowedAccountIDs {
266			if _, ok := w.accounts[id]; !ok {
267				return fmt.Errorf("%w: allowed account %q: %w", ErrPolicyInvalid, id, ErrAccountNotFound)
268			}
269			allowed[id] = struct{}{}
270		}
271	
272		w.policies[spec.ID] = &policy{
273			id:                spec.ID,
274			payerAccountID:    spec.PayerAccountID,
275			allowedAccounts:   allowed,
276			operation:         spec.Operation,
277			payee:             spec.Payee,
278			startsAt:          spec.StartsAt,
279			endsAt:            spec.EndsAt,
280			maxPerRequest:     spec.MaxPerRequest,
281			maxTotal:          spec.MaxTotal,
282			approvalThreshold: spec.ApprovalThreshold,
283			approvalWait:      spec.ApprovalWait,
284		}
285		return nil
286	}
287	
288	// Policy 查询策略视图，含当前预留中与已结算的累计金额。
289	func (w *Wallet) Policy(id string) (PolicyView, error) {
290		w.mu.Lock()
291		defer w.mu.Unlock()
292	
293		p, ok := w.policies[id]
294		if !ok {
295			return PolicyView{}, fmt.Errorf("%w: %s", ErrPolicyNotFound, id)
296		}
297		return p.view(), nil
298	}
299	
300	// DeactivatePolicy 由出资账户主动停用一条代付策略，立即停止该策略继续
301	// 受理代付。停用不可撤销。
302	//
303	// 必须使用该策略出资账户绑定当前设备的有效会话：会话不存在、不属于出资
304	// 账户、设备不符、已吊销或已到期时返回 ErrNotPolicyOwner，不改变策略、
305	// 请求或账本。策略编号、会话编号、设备缺失，或理由去掉首尾空白后为空，
306	// 返回 ErrInvalidArgument。策略不存在返回 ErrPolicyNotFound。保存与比较
307	// 理由均使用去掉首尾空白后的内容。
308	//
309	// 再次停用仍须通过会话校验：理由与首次相同时幂等返回首次结果，理由不同
310	// 返回 ErrConflict；两者都不改写首次停用信息，也不增加账本记录。尚未
311	// 开始或已经结束的策略也允许停用；停用后该编号不能再保存成新策略。
312	//
313	// 停用成功时，该策略下未到等待期限的待审批请求立即转为拒绝终态，拒绝
314	// 信息说明策略被停用并包含停用理由，决定时间为停用时间；已到（含恰到）
315	// 或超过等待期限的待审批请求进入过期终态。两类处理都不冻结余额、不占用
316	// 额度，也不产生退款；其他状态的请求与其他策略不受影响。
317	func (w *Wallet) DeactivatePolicy(policyID, sessionID, deviceID, reason string) (PolicyView, error) {
318		reason = strings.TrimSpace(reason)
319		if policyID == "" || sessionID == "" || deviceID == "" || reason == "" {
320			return PolicyView{}, fmt.Errorf("%w: policy id, session id, device id and reason are required", ErrInvalidArgument)
321		}
322	
323		w.mu.Lock()
324		defer w.mu.Unlock()
325	
326		p, ok := w.policies[policyID]
327		if !ok {
328			return PolicyView{}, fmt.Errorf("%w: %s", ErrPolicyNotFound, policyID)
329		}
330		now := w.now()
331		if err := w.checkPolicyOwnerLocked(p, sessionID, deviceID, now); err != nil {
332			return PolicyView{}, err
333		}
334	
335		if p.deactivated {
336			// 停用不可撤销：理由相同返回首次结果，理由不同返回冲突，
337			// 均不改写首次信息、不增加账本记录。
338			if p.deactivateReason == reason {
339				return p.view(), nil
340			}
341			return PolicyView{}, fmt.Errorf("%w: policy %s was already deactivated with a different reason", ErrConflict, policyID)
342		}
343	
344		p.deactivated = true
345		p.deactivatedAt = now
346		p.deactivatorAccountID = p.payerAccountID
347		p.deactivateReason = reason
348	
349		w.ledger = append(w.ledger, LedgerEntry{
350			Kind:      LedgerPolicyDeactivation,
351			AccountID: p.payerAccountID,
352			PolicyID:  p.id,
353			Reason:    reason,
354			At:        now,
355		})
356	
357		// 停用瞬间结清该策略全部待审批请求：未到等待期限的随停用立即拒绝，
358		// 已到或超过期限的进入过期终态（不能因未被查询过而变成停用拒绝）。
359		for _, req := range w.requests {
360			if req.policyID != p.id || req.state != RequestPendingApproval {
361				continue
362			}
363			if now.Before(req.waitDeadline) {
364				msg := fmt.Sprintf("policy %s deactivated by payer: %s", p.id, reason)
365				req.state = RequestRejected
366				req.rejectReason = msg
367				req.decidedAt = now
368				req.approverAccountID = p.payerAccountID
369				w.ledger = append(w.ledger, LedgerEntry{
370					Kind:      LedgerRejection,
371					AccountID: req.accountID,
372					RequestID: req.requestID,
373					Reason:    msg,
374					At:        now,
375				})
376				continue
377			}
378			req.state = RequestExpired
379			req.decidedAt = now
380			w.ledger = append(w.ledger, LedgerEntry{
381				Kind:      LedgerExpiration,
382				AccountID: req.accountID,
383				RequestID: req.requestID,
384				Reason:    "approval period expired",
385				At:        now,
386			})
387		}
388		return p.view(), nil
389	}
390	
391	// checkPolicyOwnerLocked 在持锁状态下校验停用会话：必须存在、归属策略的
392	// 出资账户、绑定当前设备、未吊销且未到期。任一不满足都返回
393	// ErrNotPolicyOwner，且不改变策略、请求或账本。
394	func (w *Wallet) checkPolicyOwnerLocked(p *policy, sessionID, deviceID string, now time.Time) error {
395		sess, ok := w.sessions[sessionID]
396		if !ok {
397			return fmt.Errorf("%w: session %s", ErrNotPolicyOwner, sessionID)
398		}
399		if sess.accountID != p.payerAccountID {
400			return fmt.Errorf("%w: session %s belongs to account %s, not payer %s", ErrNotPolicyOwner, sess.id, sess.accountID, p.payerAccountID)
401		}
402		if sess.deviceID != deviceID {
403			return fmt.Errorf("%w: session %s is bound to device %s, not %s", ErrNotPolicyOwner, sess.id, sess.deviceID, deviceID)
404		}
405		if sess.revoked {
406			return fmt.Errorf("%w: session %s revoked", ErrNotPolicyOwner, sess.id)
407		}
408		if !now.Before(sess.expiresAt) {
409			return fmt.Errorf("%w: session %s expired at %s", ErrNotPolicyOwner, sess.id, sess.expiresAt.Format(time.RFC3339))
410		}
411		return nil
412	}
413	
414	// Apply 提交一笔代付申请。
415	//
416	// 校验顺序为：申请字段 -> 使用账户 -> 会话（存在性、归属、设备、吊销、
417	// 到期）-> 幂等请求编号 -> 策略授权与额度 -> 出资账户余额。任一环节
418	// 失败都会在账本中留下带具体原因的拒绝记录，不产生任何扣款或预留。
419	//
420	// 同一使用账户以相同请求编号重复申请：策略、操作类型、收款方和预估
421	// 费用一致时直接返回已有请求（不再预留）；任一不同则返回 ErrConflict。
422	func (w *Wallet) Apply(in RequestInput) (RequestView, error) {
423		if in.EstimatedFee <= 0 {
424			return RequestView{}, w.reject(in, fmt.Errorf("%w: estimated fee must be positive", ErrInvalidAmount))
425		}
426		if in.AccountID == "" || in.SessionID == "" || in.DeviceID == "" || in.RequestID == "" || in.PolicyID == "" {
427			return RequestView{}, w.reject(in, fmt.Errorf("%w: account, session, device, policy and request id are required", ErrInvalidArgument))
428		}
429	
430		w.mu.Lock()
431		defer w.mu.Unlock()
432	
433		now := w.now()
434	
435		acc, ok := w.accounts[in.AccountID]
436		if !ok {
437			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrAccountNotFound, in.AccountID))
438		}
439		_ = acc
440	
441		sess, ok := w.sessions[in.SessionID]
442		if !ok {
443			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrSessionNotFound, in.SessionID))
444		}
445		if sess.accountID != in.AccountID {
446			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s belongs to account %s", ErrSessionAccountMismatch, sess.id, sess.accountID))
447		}
448		if sess.deviceID != in.DeviceID {
449			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s is bound to device %s", ErrSessionDeviceMismatch, sess.id, sess.deviceID))
450		}
451		if sess.revoked {
452			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s", ErrSessionRevoked, sess.id))
453		}
454		// 到期时刻及之后一律视为过期：[零值, ExpiresAt) 才有效。
455		if !now.Before(sess.expiresAt) {
456			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s expired at %s", ErrSessionExpired, sess.id, sess.expiresAt.Format(time.RFC3339)))
457		}
458	
459		key := requestKey{accountID: in.AccountID, requestID: in.RequestID}
460		if existing, ok := w.requests[key]; ok {
461			// 待审批请求到期即过期，重复申请看到的应是最新终态。
462			w.refreshPendingLocked(existing, now)
463			if existing.policyID == in.PolicyID &&
464				existing.operation == in.Operation &&
465				existing.payee == in.Payee &&
466				existing.estimatedFee == in.EstimatedFee {
467				// 幂等命中：直接返回已有结果，不再预留、不记账。
468				return existing.view(), nil
469			}
470			return RequestView{}, fmt.Errorf("%w: account %s request %s was already submitted with different content", ErrConflict, in.AccountID, in.RequestID)
471		}
472	
473		p, ok := w.policies[in.PolicyID]
474		if !ok {
475			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrPolicyNotFound, in.PolicyID))
476		}
477		// 停用后的策略不再受理新申请；历史请求的幂等查询在上方已先行处理。
478		if p.deactivated {
479			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: policy %s deactivated: %s", ErrPolicyDeactivated, p.id, p.deactivateReason))
480		}
481		if _, ok := p.allowedAccounts[in.AccountID]; !ok {
482			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: account %s is not allowed by policy %s", ErrPolicyDenied, in.AccountID, p.id))
483		}
484		if in.Operation != p.operation {
485			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: operation %q does not match policy %q", ErrPolicyDenied, in.Operation, p.operation))
486		}
487		if in.Payee != p.payee {
488			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payee %q does not match policy %q", ErrPolicyDenied, in.Payee, p.payee))
489		}
490		// 时间窗含开始、不含结束：[StartsAt, EndsAt)。
491		if now.Before(p.startsAt) || !now.Before(p.endsAt) {
492			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: current time %s is outside policy window [%s, %s)", ErrPolicyDenied,
493				now.Format(time.RFC3339), p.startsAt.Format(time.RFC3339), p.endsAt.Format(time.RFC3339)))
494		}
495		if in.EstimatedFee > p.maxPerRequest {
496			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d exceeds per-request limit %d", ErrQuotaExceeded, in.EstimatedFee, p.maxPerRequest))
497		}
498		// 预留中的费用同样占用共享累计额度。
499		if p.reservedTotal+p.spentTotal+in.EstimatedFee > p.maxTotal {
500			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
501				ErrQuotaExceeded, in.EstimatedFee, p.maxTotal, p.reservedTotal+p.spentTotal))
502		}
503	
504		payer, ok := w.accounts[p.payerAccountID]
505		if !ok {
506			// 保存策略时已校验，这里仅作防御。
507			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("payer account %s: %w", p.payerAccountID, ErrAccountNotFound))
508		}
509		if payer.available < in.EstimatedFee {
510			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, in.EstimatedFee))
511		}
512	
513		// 所有硬性检查通过：预估费用严格超过审批门槛的进入待审批，其余直接预留。
514		if p.approvalThreshold > 0 && in.EstimatedFee > p.approvalThreshold {
515			// 待审批不冻结余额、不占用共享累计额度。期限取提交时刻 + 等待时长、
516			// 策略结束时间、申请会话到期时间三者中的最早值。
517			deadline := now.Add(p.approvalWait)
518			if p.endsAt.Before(deadline) {
519				deadline = p.endsAt
520			}
521			if sess.expiresAt.Before(deadline) {
522				deadline = sess.expiresAt
523			}
524			req := &request{
525				policyID:       p.id,
526				requestID:      in.RequestID,
527				accountID:      in.AccountID,
528				payerAccountID: payer.id,
529				sessionID:      sess.id,
530				operation:      in.Operation,
531				payee:          in.Payee,
532				estimatedFee:   in.EstimatedFee,
533				state:          RequestPendingApproval,
534				createdAt:      now,
535				waitDeadline:   deadline,
536			}
537			w.requests[key] = req
538			w.ledger = append(w.ledger, LedgerEntry{
539				Kind:      LedgerPendingApproval,
540				AccountID: in.AccountID,
541				RequestID: in.RequestID,
542				Reason:    "pending approval for large amount",
543				At:        now,
544			})
545			return req.view(), nil
546		}
547	
548		// 受理：从出资账户可用余额中预留预估费用。
549		payer.available -= in.EstimatedFee
550		payer.reserved += in.EstimatedFee
551		p.reservedTotal += in.EstimatedFee
552	
553		req := &request{
554			policyID:       p.id,
555			requestID:      in.RequestID,
556			accountID:      in.AccountID,
557			payerAccountID: payer.id,
558			sessionID:      sess.id,
559			operation:      in.Operation,
560			payee:          in.Payee,
561			estimatedFee:   in.EstimatedFee,
562			state:          RequestReserved,
563			createdAt:      now,
564		}
565		w.requests[key] = req
566		w.ledger = append(w.ledger, LedgerEntry{
567			Kind:      LedgerReserve,
568			AccountID: payer.id,
569			RequestID: in.RequestID,
570			Amount:    in.EstimatedFee,
571			Reason:    "reserve estimated fee",
572			At:        now,
573		})
574		return req.view(), nil
575	}
576	
577	// Settle 结算一笔已预留的代付请求。
578	//
579	// actualFee 允许为零但不得为负、不得超过预留的预估费用。结算时扣除
580	// 实际费用并把差额退回可用余额。以相同实际费用重复结算幂等返回，不
581	// 重复记账；不同实际费用返回 ErrConflict。已取消的请求不能结算。
582	func (w *Wallet) Settle(accountID, requestID string, actualFee int64) (RequestView, error) {
583		if actualFee < 0 {
584			return RequestView{}, fmt.Errorf("%w: actual fee must not be negative", ErrInvalidAmount)
585		}
586		w.mu.Lock()
587		defer w.mu.Unlock()
588	
589		req, p, err := w.lookupRequest(accountID, requestID)
590		if err != nil {
591			return RequestView{}, err
592		}
593		w.refreshPendingLocked(req, w.now())
594		switch req.state {
595		case RequestSettled:
596			if req.actualFee == actualFee {
597				return req.view(), nil
598			}
599			return RequestView{}, fmt.Errorf("%w: request %s already settled with actual fee %d", ErrConflict, requestID, req.actualFee)
600		case RequestCancelled:
601			return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadyCancelled, requestID)
602		case RequestPendingApproval, RequestRejected, RequestExpired:
603			// 结算只允许处理已预留请求。
604			return RequestView{}, fmt.Errorf("%w: request %s is %v, only reserved requests can be settled", ErrRequestNotReserved, requestID, req.state)
605		}
606	
607		if actualFee > req.estimatedFee {
608			// 拒绝并保留预留。
609			return RequestView{}, fmt.Errorf("%w: actual %d > estimated %d for request %s", ErrSettleTooLarge, actualFee, req.estimatedFee, requestID)
610		}
611	
612		now := w.now()
613		payer := w.accounts[req.payerAccountID]
614		refund := req.estimatedFee - actualFee
615	
616		// 扣除实际费用、退回差额、释放共享额度。
617		payer.reserved -= req.estimatedFee
618		payer.available += refund
619		p.reservedTotal -= req.estimatedFee
620		p.spentTotal += actualFee
621	
622		req.state = RequestSettled
623		req.actualFee = actualFee
624		req.settledAt = now
625	
626		w.ledger = append(w.ledger, LedgerEntry{
627			Kind:      LedgerSettle,
628			AccountID: payer.id,
629			RequestID: requestID,
630			Amount:    actualFee,
631			Reason:    "settle actual fee",
632			At:        now,
633		})
634		if refund > 0 {
635			w.ledger = append(w.ledger, LedgerEntry{
636				Kind:      LedgerRefund,
637				AccountID: payer.id,
638				RequestID: requestID,
639				Amount:    refund,
640				Reason:    "refund estimated-minus-actual fee",
641				At:        now,
642			})
643		}
644		return req.view(), nil
645	}
646	
647	// Cancel 取消一笔尚未结算的代付请求。
648	//
649	// 待审批请求取消后直接进入取消终态，不产生退款（本就没有冻结余额）；
650	// 已预留请求取消后全部预留退回。已结算的请求不能取消；重复取消幂等
651	// 返回，不重复记账。已拒绝或已过期的请求不能取消。
652	func (w *Wallet) Cancel(accountID, requestID string) (RequestView, error) {
653		w.mu.Lock()
654		defer w.mu.Unlock()
655	
656		req, p, err := w.lookupRequest(accountID, requestID)
657		if err != nil {
658			return RequestView{}, err
659		}
660		now := w.now()
661		w.refreshPendingLocked(req, now)
662		switch req.state {
663		case RequestCancelled:
664			return req.view(), nil
665		case RequestSettled:
666			return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadySettled, requestID)
667		case RequestPendingApproval:
668			// 待审批取消：无资金冻结，直接留取消终态。
669			req.state = RequestCancelled
670			req.decidedAt = now
671			w.ledger = append(w.ledger, LedgerEntry{
672				Kind:      LedgerCancellation,
673				AccountID: req.accountID,
674				RequestID: req.requestID,
675				Reason:    "cancel pending-approval request",
676				At:        now,
677			})
678			return req.view(), nil
679		case RequestRejected, RequestExpired:
680			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot cancel", ErrRequestNotReserved, requestID, req.state)
681		}
682	
683		// 已预留：退回全部预留。
684		payer := w.accounts[req.payerAccountID]
685	
686		payer.reserved -= req.estimatedFee
687		payer.available += req.estimatedFee
688		p.reservedTotal -= req.estimatedFee
689	
690		req.state = RequestCancelled
691	
692		w.ledger = append(w.ledger, LedgerEntry{
693			Kind:      LedgerRefund,
694			AccountID: payer.id,
695			RequestID: requestID,
696			Amount:    req.estimatedFee,
697			Reason:    "refund reserved fee on cancel",
698			At:        now,
699		})
700		return req.view(), nil
701	}
702	
703	// Approve 批准一笔待审批的大额代付请求。
704	//
705	// 审批必须使用该策略出资账户绑定当前设备的有效会话；其他账户或无效
706	// 会话返回 ErrNotApprover 无权审批，且不改变请求。批准时再次检查出资
707	// 余额与共享剩余额度，足够才一次性预留全部预估费用并转为已预留；不足
708	// 时返回具体原因，保留待审批状态，期限内可再次批准。
709	//
710	// 已批准并处于预留或结算状态的请求重复批准只返回当前结果，不重复预留；
711	// 已拒绝、过期或取消的请求不能批准。截止时刻及之后不能批准。
712	func (w *Wallet) Approve(accountID, requestID, sessionID, deviceID string) (RequestView, error) {
713		if accountID == "" || requestID == "" || sessionID == "" || deviceID == "" {
714			return RequestView{}, fmt.Errorf("%w: account, request, session and device ids are required", ErrInvalidArgument)
715		}
716		w.mu.Lock()
717		defer w.mu.Unlock()
718	
719		now := w.now()
720		req, p, err := w.lookupRequest(accountID, requestID)
721		if err != nil {
722			return RequestView{}, err
723		}
724		if err := w.checkApproverLocked(req, sessionID, deviceID, now); err != nil {
725			return RequestView{}, err
726		}
727		w.refreshPendingLocked(req, now)
728		if req.state == RequestExpired {
729			return RequestView{}, fmt.Errorf("%w: approval deadline %s passed", ErrApprovalExpired, req.waitDeadline.Format(time.RFC3339))
730		}
731	
732		switch req.state {
733		case RequestPendingApproval:
734			payer := w.accounts[req.payerAccountID]
735			if payer.available < req.estimatedFee {
736				return RequestView{}, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, req.estimatedFee)
737			}
738			if p.reservedTotal+p.spentTotal+req.estimatedFee > p.maxTotal {
739				return RequestView{}, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
740					ErrQuotaExceeded, req.estimatedFee, p.maxTotal, p.reservedTotal+p.spentTotal)
741			}
742			// 一次性预留全部预估费用。
743			payer.available -= req.estimatedFee
744			payer.reserved += req.estimatedFee
745			p.reservedTotal += req.estimatedFee
746	
747			req.state = RequestReserved
748			req.decidedAt = now
749			req.approverAccountID = payer.id
750	
751			w.ledger = append(w.ledger,
752				LedgerEntry{
753					Kind:      LedgerReserve,
754					AccountID: payer.id,
755					RequestID: req.requestID,
756					Amount:    req.estimatedFee,
757					Reason:    "reserve estimated fee on approval",
758					At:        now,
759				},
760				LedgerEntry{
761					Kind:      LedgerApproval,
762					AccountID: req.accountID,
763					RequestID: req.requestID,
764					Reason:    "approve large-amount request",
765					At:        now,
766				},
767			)
768			return req.view(), nil
769		case RequestReserved, RequestSettled:
770			// 已批准：重复批准幂等返回，不重复预留。
771			return req.view(), nil
772		default:
773			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot approve", ErrRequestNotPending, requestID, req.state)
774		}
775	}
776	
777	// Reject 拒绝一笔待审批的大额代付请求。
778	//
779	// 拒绝必须使用该策略出资账户绑定当前设备的有效会话；其他账户或无效
780	// 会话返回 ErrNotApprover 无权审批，且不改变请求。拒绝理由为空或全为
781	// 空白时返回 ErrInvalidArgument 参数错误，请求保持不变。
782	//
783	// 重复拒绝且理由一致时幂等返回，不重复留痕；理由不同返回 ErrConflict。
784	// 已批准（含预留、结算）、已过期或已取消的请求不能拒绝。
785	func (w *Wallet) Reject(accountID, requestID, sessionID, deviceID, reason string) (RequestView, error) {
786		if strings.TrimSpace(reason) == "" {
787			return RequestView{}, fmt.Errorf("%w: reject reason must not be empty or blank", ErrInvalidArgument)
788		}
789		if accountID == "" || requestID == "" || sessionID == "" || deviceID == "" {
790			return RequestView{}, fmt.Errorf("%w: account, request, session and device ids are required", ErrInvalidArgument)
791		}
792		w.mu.Lock()
793		defer w.mu.Unlock()
794	
795		now := w.now()
796		req, _, err := w.lookupRequest(accountID, requestID)
797		if err != nil {
798			return RequestView{}, err
799		}
800		if err := w.checkApproverLocked(req, sessionID, deviceID, now); err != nil {
801			return RequestView{}, err
802		}
803		w.refreshPendingLocked(req, now)
804	
805		switch req.state {
806		case RequestPendingApproval:
807			req.state = RequestRejected
808			req.rejectReason = reason
809			req.decidedAt = now
810			req.approverAccountID = req.payerAccountID
811	
812			w.ledger = append(w.ledger, LedgerEntry{
813				Kind:      LedgerRejection,
814				AccountID: req.accountID,
815				RequestID: req.requestID,
816				Reason:    reason,
817				At:        now,
818			})
819			return req.view(), nil
820		case RequestRejected:
821			if req.rejectReason == reason {
822				return req.view(), nil
823			}
824			return RequestView{}, fmt.Errorf("%w: request %s already rejected with a different reason", ErrConflict, requestID)
825		default:
826			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot reject", ErrRequestNotPending, requestID, req.state)
827		}
828	}
829	
830	// checkApproverLocked 在持锁状态下校验审批会话：必须存在、归属出资账户、
831	// 绑定当前设备、未吊销且未过期。任一不满足都返回 ErrNotApprover，且不
832	// 改变请求。
833	func (w *Wallet) checkApproverLocked(req *request, sessionID, deviceID string, now time.Time) error {
834		sess, ok := w.sessions[sessionID]
835		if !ok {
836			return fmt.Errorf("%w: session %s", ErrNotApprover, sessionID)
837		}
838		if sess.accountID != req.payerAccountID {
839			return fmt.Errorf("%w: session %s belongs to account %s, not payer %s", ErrNotApprover, sess.id, sess.accountID, req.payerAccountID)
840		}
841		if sess.deviceID != deviceID {
842			return fmt.Errorf("%w: session %s is bound to device %s, not %s", ErrNotApprover, sess.id, sess.deviceID, deviceID)
843		}
844		if sess.revoked {
845			return fmt.Errorf("%w: session %s revoked", ErrNotApprover, sess.id)
846		}
847		if !now.Before(sess.expiresAt) {
848			return fmt.Errorf("%w: session %s expired at %s", ErrNotApprover, sess.id, sess.expiresAt.Format(time.RFC3339))
849		}
850		return nil
851	}
852	
853	// refreshPendingLocked 在持锁状态下检查待审批请求是否已到期限；到期
854	// （含到期时刻）则转为过期终态并记账。必须在持锁状态下调用。
855	func (w *Wallet) refreshPendingLocked(req *request, now time.Time) {
856		if req.state != RequestPendingApproval {
857			return
858		}
859		if now.Before(req.waitDeadline) {
860			return
861		}
862		req.state = RequestExpired
863		req.decidedAt = now
864		w.ledger = append(w.ledger, LedgerEntry{
865			Kind:      LedgerExpiration,
866			AccountID: req.accountID,
867			RequestID: req.requestID,
868			Reason:    "approval period expired",
869			At:        now,
870		})
871	}
872	
873	// Request 查询某使用账户下的代付请求。待审批请求到期即转为过期终态，
874	// 查询结果反映最新状态。
875	func (w *Wallet) Request(accountID, requestID string) (RequestView, error) {
876		w.mu.Lock()
877		defer w.mu.Unlock()
878	
879		req, _, err := w.lookupRequest(accountID, requestID)
880		if err != nil {
881			return RequestView{}, err
882		}
883		w.refreshPendingLocked(req, w.now())
884		return req.view(), nil
885	}
886	
887	// Ledger 返回全部账本记录的副本，按产生顺序排列。
888	// 申请被拒绝的记录（Kind 为 LedgerRejection）也包含在内并带有原因。
889	func (w *Wallet) Ledger() []LedgerEntry {
890		w.mu.Lock()
891		defer w.mu.Unlock()
892	
893		out := make([]LedgerEntry, len(w.ledger))
894		copy(out, w.ledger)
895		return out
896	}
897	
898	// AccountLedger 返回与指定账户相关的账本记录副本。
899	//
900	// 对出资账户返回预留、扣减、退回等资金变动记录；对待审批、批准、拒绝、
901	// 取消、过期等状态记录（无金额变动），其 AccountID 为发起申请的使用
902	// 账户，因此按使用账户查询可看到该请求的完整状态留痕。
903	func (w *Wallet) AccountLedger(accountID string) []LedgerEntry {
904		w.mu.Lock()
905		defer w.mu.Unlock()
906	
907		var out []LedgerEntry
908		for _, e := range w.ledger {
909			if e.AccountID == accountID {
910				out = append(out, e)
911			}
912		}
913		return out
914	}
915	
916	// lookupRequest 必须在持锁状态下调用。
917	func (w *Wallet) lookupRequest(accountID, requestID string) (*request, *policy, error) {
918		req, ok := w.requests[requestKey{accountID: accountID, requestID: requestID}]
919		if !ok {
920			return nil, nil, fmt.Errorf("%w: account %s request %s", ErrRequestNotFound, accountID, requestID)
921		}
922		return req, w.policies[req.policyID], nil
923	}
924	
925	// reject 记录无需持锁快速校验阶段的拒绝（当前没有此类调用，保留对称接口）。
926	func (w *Wallet) reject(in RequestInput, cause error) error {
927		w.mu.Lock()
928		defer w.mu.Unlock()
929		w.appendRejection(in, w.now(), cause)
930		return cause
931	}
932	
933	// rejectLocked 在持锁状态下记录拒绝原因并原样返回错误。
934	func (w *Wallet) rejectLocked(in RequestInput, at time.Time, cause error) error {
935		w.appendRejection(in, at, cause)
936		return cause
937	}
938	
939	// appendRejection 必须在持锁状态下调用。拒绝记录不涉及金额变动，
940	// 只记录使用账户、请求编号与具体原因。
941	func (w *Wallet) appendRejection(in RequestInput, at time.Time, cause error) {
942		w.ledger = append(w.ledger, LedgerEntry{
943			Kind:      LedgerRejection,
944			AccountID: in.AccountID,
945			RequestID: in.RequestID,
946			Reason:    cause.Error(),
947			At:        at,
948		})
949	}
950	
951	func (a *account) view() AccountView {
952		return AccountView{
953			ID: a.id,
954			Balances: Balances{
955				Available: a.available,
956				Reserved:  a.reserved,
957			},
958			CreatedAt: a.createdAt,
959		}
960	}
961	
962	func (s *session) view() SessionView {
963		state := SessionActive
964		if s.revoked {
965			state = SessionRevoked
966		}
967		return SessionView{
968			ID:        s.id,
969			AccountID: s.accountID,
970			DeviceID:  s.deviceID,
971			ExpiresAt: s.expiresAt,
972			State:     state,
973			CreatedAt: s.createdAt,
974		}
975	}
976	
977	func (p *policy) view() PolicyView {
978		ids := make([]string, 0, len(p.allowedAccounts))
979		for id := range p.allowedAccounts {
980			ids = append(ids, id)
981		}
982		return PolicyView{
983			PolicySpec: PolicySpec{
984				ID:                p.id,
985				PayerAccountID:    p.payerAccountID,
986				AllowedAccountIDs: ids,
987				Operation:         p.operation,
988				Payee:             p.payee,
989				StartsAt:          p.startsAt,
990				EndsAt:            p.endsAt,
991				MaxPerRequest:     p.maxPerRequest,
992				MaxTotal:          p.maxTotal,
993				ApprovalThreshold: p.approvalThreshold,
994				ApprovalWait:      p.approvalWait,
995			},
996			ReservedTotal:        p.reservedTotal,
997			SpentTotal:           p.spentTotal,
998			Deactivated:          p.deactivated,
999			DeactivatedAt:        p.deactivatedAt,
1000			DeactivatorAccountID: p.deactivatorAccountID,
1001			DeactivateReason:     p.deactivateReason,
1002		}
1003	}
1004	
1005	func (r *request) view() RequestView {
1006		return RequestView{
1007			PolicyID:          r.policyID,
1008			RequestID:         r.requestID,
1009			AccountID:         r.accountID,
1010			PayerAccountID:    r.payerAccountID,
1011			Operation:         r.operation,
1012			Payee:             r.payee,
1013			EstimatedFee:      r.estimatedFee,
1014			ActualFee:         r.actualFee,
1015			State:             r.state,
1016			CreatedAt:         r.createdAt,
1017			SettledAt:         r.settledAt,
1018			WaitDeadline:      r.waitDeadline,
1019			DecidedAt:         r.decidedAt,
1020			ApproverAccountID: r.approverAccountID,
1021			RejectReason:      r.rejectReason,
1022		}
1023	}
