func TestRejectionLeavesLedgerReasonAndNoMoneyMovement(t *testing.T) {
	w, _ := setupApply(t)
	in := baseApply()
	in.DeviceID = "wrong"
	if _, err := w.Apply(in); !errors.Is(err, ErrSessionDeviceMismatch) {
		t.Fatal(err)
	}
	all := w.Ledger()
	if len(all) != 1 || all[0].Kind != LedgerRejection || all[0].RequestID != "r1" || all[0].Amount != 0 {
