347		if _, err := w.Reject("u1", "r1", "sa", "dev-approve", "manual no"); err != nil {
348			t.Fatal(err)
349		}
350		reserved := approvalApply()
351		reserved.RequestID = "r2"
352		reserved.EstimatedFee = 8
353		if _, err := w.Apply(reserved); err != nil {
354			t.Fatal(err)
355		}
356		if _, err := w.Settle("u1", "r2", 8); err != nil {
357			t.Fatal(err)
358		}
359		cancelable := approvalApply()
360		cancelable.RequestID = "r3"
361		cancelable.EstimatedFee = 7
362		if _, err := w.Apply(cancelable); err != nil {
363			t.Fatal(err)
364		}
365		if _, err := w.Cancel("u1", "r3"); err != nil {
366			t.Fatal(err)
367		}
368		before := len(w.Ledger())
369	
370		if _, err := w.DeactivatePolicy("p-approval", "sa", "dev-approve", "stop"); err != nil {
371			t.Fatal(err)
372		}
373		// 停用只增加 1 条停用留痕（p-approval 下已无待审批请求）。
374		if got := len(w.Ledger()) - before; got != 1 {
375			t.Fatalf("ledger grew by %d, want 1", got)
376		}
377	
378		// 终态记录不改写。
379		if r, _ := w.Request("u1", "r1"); r.State != RequestRejected || r.RejectReason != "manual no" {
380			t.Fatalf("rejected rewritten: %+v", r)
381		}
382		if r, _ := w.Request("u1", "r2"); r.State != RequestSettled || r.ActualFee != 8 {
383			t.Fatalf("settled rewritten: %+v", r)
384		}
385		if r, _ := w.Request("u1", "r3"); r.State != RequestCancelled {
386			t.Fatalf("cancelled rewritten: %+v", r)
387		}
388		// 另一条策略的待审批请求保持可批准。
389		if r, _ := w.Request("u1", "ro1"); r.State != RequestPendingApproval {
390			t.Fatalf("other policy request state = %v", r.State)
391		}
392		if _, err := w.Approve("u1", "ro1", "sa", "dev-approve"); err != nil {
393			t.Fatalf("other policy pending should still be approvable: %v", err)
394		}
395		if pv, _ := w.Policy("p-other"); pv.Deactivated {
396			t.Fatal("other policy should stay active")
397		}
398	}
